// Resolve the latest version of each package published on or before a cutoff.
const cutoff = new Date(process.argv[2]);
const names = process.argv.slice(3);
const out = [];
for (const name of names) {
	const response = await fetch(`https://registry.npmjs.org/${name.replace('/', '%2f')}`, {
		headers: { accept: 'application/vnd.npm.install-v1+json' },
	});
	if (!response.ok) throw new Error(`${name}: ${response.status}`);
	const body = await response.json();
	const times = Object.entries(body.time ?? {}).filter(
		([version]) => version !== 'created' && version !== 'modified',
	);
	const eligible = times
		.filter(([version, when]) => new Date(when) <= cutoff && !/-/.test(version))
		.sort((a, b) => new Date(a[1]) - new Date(b[1]));
	const picked = eligible[eligible.length - 1];
	out.push({ name, version: picked?.[0] ?? null, published: picked?.[1] ?? null });
}
console.log(JSON.stringify(out, null, 2));

