cat > /tmp/hr-tools/pin.mjs <<'EOF'
// Fetch an exact version tarball, verify its registry-declared integrity, and
// extract it over the installed placement. Emits one ledger line per package.
import { createHash } from 'node:crypto';
import { mkdtemp, rm, writeFile, mkdir, readdir, rename } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import * as path from 'node:path';

const root = process.argv[2];
const cutoff = process.argv[3];
const specs = process.argv.slice(4);
const ledger = [];
for (const spec of specs) {
	const at = spec.lastIndexOf('@');
	const name = spec.slice(0, at);
	const version = spec.slice(at + 1);
	const packument = await (await fetch(`https://registry.npmjs.org/${name.replace('/', '%2f')}`)).json();
	const manifest = packument.versions[version];
	if (!manifest) throw new Error(`${spec} not published`);
	const url = manifest.dist.tarball;
	const bytes = Buffer.from(await (await fetch(url)).arrayBuffer());
	const sha1 = createHash('sha1').update(bytes).digest('hex');
	const sha512 = `sha512-${createHash('sha512').update(bytes).digest('base64')}`;
	if (manifest.dist.shasum !== sha1) throw new Error(`${spec} shasum mismatch`);
	const staging = await mkdtemp(path.join(tmpdir(), 'hr-pin-'));
	const archive = path.join(staging, 'package.tgz');
	await writeFile(archive, bytes);
	execFileSync('tar', ['-xzf', archive, '-C', staging]);
	const destination = path.join(root, 'node_modules', name);
	await rm(destination, { recursive: true, force: true });
	await mkdir(path.dirname(destination), { recursive: true });
	await rename(path.join(staging, 'package'), destination);
	await rm(staging, { recursive: true, force: true });
	ledger.push({
		name,
		version,
		tarball: url,
		published: packument.time[version],
		integrity: manifest.dist.integrity ?? sha512,
		tarballSha256: createHash('sha256').update(bytes).digest('hex'),
		cutoff,
	});
}
console.log(JSON.stringify(ledger, null, 2));
EOF
